  --miku-character-width: 38%;
  --miku-character-height: calc(100% + 54px);
  --miku-character-right: 2%;
  --miku-character-bottom: -3px;
  --codex-base-accent: #e67db5 !important;
  --codex-base-ink: #51364f !important;
  --codex-base-surface: #fff6fb !important;
  --color-background-surface: #fff6fb !important;
  --color-background-surface-under: #fdebf4 !important;
  --color-background-panel: #fceaf3 !important;
  --color-background-control: rgba(255, 255, 255, .86) !important;
  --color-background-control-opaque: #fffdfd !important;
  --color-background-editor-opaque: #fffdfd !important;
  --color-background-elevated-primary: rgba(255, 255, 255, .96) !important;
  --color-background-elevated-primary-opaque: #fffdfd !important;
  --color-background-elevated-secondary: rgba(230, 125, 181, .11) !important;
  --color-background-elevated-secondary-opaque: #e2f7fb !important;
  --color-background-button-primary: #e67db5 !important;
  --color-background-button-secondary: rgba(230, 125, 181, .12) !important;
  --color-background-button-tertiary: rgba(230, 125, 181, .08) !important;
  --color-background-accent: #fbdbea !important;
  --color-background-accent-hover: #f6c9dd !important;
  --color-background-accent-active: #efb9d1 !important;
