  --color-border-heavy: rgba(207, 100, 162, .36) !important;
  --color-border-focus: rgba(207, 100, 162, .72) !important;
  --color-icon-primary: #6e4a65 !important;
  --color-icon-secondary: #987a90 !important;
  --color-icon-tertiary: #c5a6ba !important;
  --color-icon-accent: #d96aa6 !important;
  --color-text-foreground: #51364f !important;
  --color-text-foreground-secondary: #846578 !important;
  --color-text-foreground-tertiary: #a98b9e !important;
  --color-text-accent: #c75d98 !important;
  --color-text-on-accent: #fffdfd !important;
  --color-text-button-primary: #fffdfd !important;
}

html, body { color: var(--miku-ink) !important; background: var(--miku-canvas) !important; font-family: "Microsoft YaHei UI", "Segoe UI", sans-serif !important; }
body { background: linear-gradient(135deg, #f4fdff, #e6f8fc 52%, #f9efff) !important; }
[class~="group/application-menu-top-bar"] { color: var(--miku-ink) !important; background: rgba(243, 253, 255, .9) !important; border-bottom: 1px solid var(--miku-line-soft) !important; backdrop-filter: blur(14px) !important; }
[class~="group/application-menu-top-bar"] button, [class~="group/application-menu-top-bar"] svg { color: var(--miku-ink) !important; }
aside.app-shell-left-panel { color: var(--miku-ink) !important; background: linear-gradient(180deg, rgba(239, 252, 255, .96), rgba(229, 247, 252, .94)) !important; border-color: var(--miku-line-soft) !important; box-shadow: inset -1px 0 var(--miku-line-soft) !important; backdrop-filter: blur(16px) !important; }
aside.app-shell-left-panel nav { background: transparent !important; }
aside.app-shell-left-panel button, aside.app-shell-left-panel a { color: #326f82 !important; transition: color 160ms ease, background-color 160ms ease, transform 160ms ease !important; }
aside.app-shell-left-panel button:hover, aside.app-shell-left-panel a:hover { color: var(--miku-accent-deep) !important; background: rgba(24, 184, 200, .1) !important; }
aside.app-shell-left-panel [class~="bg-token-list-hover-background"], aside.app-shell-left-panel [aria-current="page"] { color: #087f9a !important; background: linear-gradient(90deg, rgba(195, 243, 248, .9), rgba(244, 253, 255, .76)) !important; box-shadow: inset 3px 0 #e67db5, inset 0 0 0 1px var(--miku-line-soft) !important; }
aside.app-shell-left-panel svg, aside.app-shell-left-panel [class*="text-token"] { color: currentColor !important; }
aside.app-shell-left-panel [data-app-action-sidebar-section-heading] { color: #96778b !important; }
aside.app-shell-left-panel [aria-label="打开个人资料菜单"] { border-top-color: var(--miku-line-soft) !important; background-color: rgba(245, 253, 255, .78) !important; }
main { position: relative !important; isolation: isolate; overflow: hidden !important; color: var(--miku-ink) !important; background: linear-gradient(130deg, rgba(250, 255, 255, .94), rgba(239, 251, 254, .88)) !important; border-color: var(--miku-line-soft) !important; border-radius: 16px 0 0 0 !important; }
main > header { min-height: 72px !important; color: var(--miku-ink) !important; background: rgba(247, 254, 255, .72) !important; border-color: var(--miku-line-soft) !important; backdrop-filter: blur(15px) !important; }
[role="main"] { color: var(--miku-ink) !important; background: transparent !important; scrollbar-color: rgba(24, 174, 190, .46) transparent; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) { min-height: 100% !important; padding-top: 42px !important; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child { flex: 0 0 520px !important; min-height: 520px !important; align-items: flex-start !important; padding-bottom: 0 !important; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child { position: relative !important; isolation: isolate; width: calc(100% - 48px) !important; max-width: 1070px !important; height: 330px !important; min-height: 330px !important; flex: 0 1 auto !important; padding: 0 !important; overflow: visible !important; border: 1px solid rgba(230, 125, 181, .40) !important; border-radius: 22px !important; background: var(--miku-hero) center / cover no-repeat !important; box-shadow: var(--miku-shadow), inset 0 0 0 4px rgba(255, 255, 255, .3) !important; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child::before { content: ""; position: absolute; inset: 0; border-radius: inherit; background: linear-gradient(90deg, rgba(255,255,255,.10), rgba(235,122,170,.06) 42%, transparent 68%); pointer-events: none; z-index: 1; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child::after { content: ""; position: absolute; z-index: 3; right: var(--miku-character-right); bottom: var(--miku-character-bottom); width: var(--miku-character-width); height: var(--miku-character-height); background: var(--miku-character) center bottom / contain no-repeat; filter: drop-shadow(0 14px 18px rgba(128, 82, 112, .20)); pointer-events: none; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child { position: relative; z-index: 2; box-sizing: border-box; height: 100%; align-items: center !important; justify-content: flex-start !important; padding: 92px 40px 18px 62px !important; visibility: hidden !important; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child > div:first-child { width: min(53%, 500px) !important; align-items: flex-start !important; gap: 0 !important; }
[role="main"]:has([data-testid="home-icon"]) [data-testid="home-icon"] { display: none !important; }
[role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"] { display: flex !important; flex-direction: column !important; align-items: flex-start !important; max-width: 100% !important; color: #51364f !important; font: 600 0/1.35 "Microsoft YaHei UI", "Segoe UI", sans-serif !important; text-align: left !important; opacity: 1 !important; pointer-events: auto !important; }
[role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"]::before { content: "今天想让昔涟陪你做什么？"; display: block; color: #51364f; font: 600 31px/1.35 "Microsoft YaHei UI", "Segoe UI", sans-serif; white-space: nowrap; }
[role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"]::after { content: "云端星海已就绪，让灵感一路发光 ✦"; display: block; margin-top: 14px; color: #846578; font: 400 15px/1.6 "Microsoft YaHei UI", "Segoe UI", sans-serif; }
[role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"] button { display: none !important; }
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:nth-child(2) { left: 34px !important; right: 34px !important; top: 100% !important; margin-top: -18px !important; }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions { overflow: visible !important; }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button { position: relative !important; min-height: 180px !important; padding: 25px 18px 18px !important; align-items: stretch !important; justify-content: flex-start !important; color: #68495f !important; border: 1px solid rgba(230, 125, 181, .28) !important; border-radius: 17px !important; background: rgba(255, 255, 255, .9) !important; box-shadow: 0 9px 19px rgba(128, 82, 112, .13), inset 0 0 0 3px rgba(255,255,255,.6) !important; transition: transform 180ms ease, box-shadow 180ms ease, background-color 180ms ease !important; }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button:hover { transform: translateY(-4px) !important; background: #fffdfd !important; box-shadow: 0 14px 27px rgba(128, 82, 112, .19), 0 0 0 2px rgba(24, 184, 200, .1) !important; }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button > span:first-child { justify-content: center !important; }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button > span:first-child > span:first-child { width: 48px !important; height: 48px !important; justify-content: center !important; margin: 0 auto; color: #fff !important; border: 1px solid rgba(216, 106, 166, .26); border-radius: 50%; background: linear-gradient(145deg, #f0a0c7, #e978b1) !important; box-shadow: 0 0 0 7px rgba(250, 220, 235, .82), 0 5px 12px rgba(128, 82, 112, .19); }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button svg { width: 23px !important; height: 23px !important; color: #fff !important; }
[role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button > span:last-child { align-items: center !important; padding-bottom: 18px; text-align: center !important; }
.composer-surface-chrome { color: var(--miku-ink) !important; border: 1px solid rgba(31, 149, 174, .34) !important; border-radius: 18px !important; background: rgba(255, 255, 255, .9) !important; box-shadow: 0 10px 26px rgba(128, 82, 112, .14), inset 0 0 0 3px rgba(255,255,255,.58) !important; backdrop-filter: blur(16px) saturate(.95) !important; }
.ProseMirror { color: var(--miku-ink) !important; caret-color: var(--miku-accent) !important; }
.ProseMirror .placeholder, .ProseMirror [data-placeholder] { color: #b497a9 !important; }
button[class~="bg-token-foreground"] { color: #fff !important; background: linear-gradient(145deg, #f0a0c7, #e978b1) !important; box-shadow: 0 5px 12px rgba(26, 135, 166, .24) !important; }
article, [data-message-author-role] { color: var(--miku-ink) !important; }
pre, code { border-color: var(--miku-line-soft) !important; background: rgba(230, 248, 252, .92) !important; }
[role="dialog"], [role="menu"], [data-radix-popper-content-wrapper] > div { color: var(--miku-ink) !important; border-color: var(--miku-line) !important; background: rgba(255, 255, 255, .97) !important; box-shadow: var(--miku-shadow) !important; }
button:focus-visible, a:focus-visible, [role="button"]:focus-visible { outline-color: var(--miku-accent-deep) !important; outline-offset: 2px !important; }
div[data-app-shell-main-content-top-fade="visible"] { display: none; }
@media (max-width: 900px) { :root { --miku-character-width: 58%; --miku-character-height: calc(100% + 80px); --miku-character-right: 0%; } main:has([data-testid="home-icon"]) > header::before, main:has([data-testid="home-icon"]) > header::after { display: none; } [role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) { padding-top: 18px !important; } [role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child { flex-basis: 465px !important; min-height: 465px !important; } [role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child { height: 285px !important; min-height: 285px !important; } [role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child { padding: 76px 22px 15px 35px !important; } [role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child > div:first-child { width: 60% !important; } [role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"]::before { font-size: 23px !important; } [role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"]::after { margin-top: 9px; font-size: 12px; } [role="main"]:has([data-testid="home-icon"]) .group\/home-suggestions button { min-height: 155px !important; padding-inline: 10px !important; } }
@media (max-width: 700px) { :root { --miku-character-width: 70%; --miku-character-height: calc(100% + 46px); --miku-character-right: -7%; } [role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child > div:first-child > div:first-child { width: 82% !important; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }

/* Xilian: show the full hero head */
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child::after { display: none !important; }

/* Xilian: pet overlay must not cover the desktop */
html.compact-window,
html.compact-window body,
html.compact-window #root,
html.compact-window main,
html.compact-window section {
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
}

/* Xilian: sharp full-width hero */
[role="main"]:has([data-testid="home-icon"]) > div:has([data-testid="home-icon"]) > div:first-child > div:first-child::before {
  background: linear-gradient(90deg, rgba(255,255,255,.22), rgba(255,255,255,.05) 34%, transparent 48%) !important;
}
[role="main"]:has([data-testid="home-icon"]) [data-feature="game-source"] {
  padding: 20px 24px 18px !important;
  border: 1px solid rgba(255,255,255,.62) !important;
  border-radius: 18px !important;
  background: rgba(255,255,255,.84) !important;
  box-shadow: 0 12px 28px rgba(62,75,130,.14), inset 0 0 0 2px rgba(255,255,255,.42) !important;
  backdrop-filter: blur(8px) saturate(.96) !important;
}

/* Xilian: themed sidebar navigation */
aside.app-shell-left-panel {
  background: linear-gradient(180deg, rgba(249,252,255,.97), rgba(238,244,255,.94)) !important;
  border-right: 1px solid rgba(111,156,255,.18) !important;
